package com.configmonitor.app;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;
public final class MonitorWidget extends AppWidgetProvider {
 private static final Handler main=new Handler(Looper.getMainLooper());private static boolean pending;
 public static void refresh(){synchronized(MonitorWidget.class){if(pending)return;pending=true;}main.postDelayed(()->{synchronized(MonitorWidget.class){pending=false;}update(App.app);},1000);}
 static void update(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=m.getAppWidgetIds(new ComponentName(c,MonitorWidget.class));if(ids.length==0)return;JSONArray nodes=App.db.all();int good=0,bad=0,enabled=0;for(int i=0;i<nodes.length();i++){JSONObject n=nodes.optJSONObject(i);if(n.optBoolean("enabled",true)){enabled++;if(n.optString("state").equals("good")||n.optString("state").equals("slow"))good++;else if(n.optString("state").equals("bad"))bad++;}}
  boolean running=App.prefs.getBoolean("running",false);RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.monitor_widget);v.setTextViewText(R.id.widget_status,App.t(running?"پایش فعال است":"پایش متوقف است",running?"Monitoring active":"Monitoring paused"));v.setTextViewText(R.id.widget_counts,App.t("سالم "+Digits.fa(""+good)+"  •  قطع "+Digits.fa(""+bad)+"  •  فعال "+Digits.fa(""+enabled),"Online "+good+"  •  Down "+bad+"  •  Enabled "+enabled));v.setTextViewText(R.id.widget_toggle,App.t(running?"توقف پایش":"شروع پایش",running?"Pause":"Start"));v.setTextViewText(R.id.widget_open,App.t("بازکردن برنامه","Open app"));
  PendingIntent open=PendingIntent.getActivity(c,90,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent toggle=PendingIntent.getBroadcast(c,91,new Intent(c,MonitorWidget.class).setAction("com.configmonitor.WIDGET_TOGGLE"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.widget_open,open);v.setOnClickPendingIntent(R.id.widget_root,open);v.setOnClickPendingIntent(R.id.widget_toggle,toggle);for(int id:ids)m.updateAppWidget(id,v);
 }
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){update(c);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if("com.configmonitor.WIDGET_TOGGLE".equals(i.getAction())){try{if(App.prefs.getBoolean("running",false)){App.prefs.edit().putBoolean("running",false).apply();Alerts.stop();c.stopService(new Intent(c,MonitorService.class));}else MonitorService.command(c,"start",0);}catch(Exception e){c.startActivity(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}App.update();update(c);}}
}
